package com.bankrowbreaks;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BankRowBreaksConfig.GROUP)
public interface BankRowBreaksConfig extends Config
{
    String GROUP = "bank-row-breaks";

    @Range(min = 0, max = 7)
    @ConfigItem(keyName = "indent", name = "Indent", description = "Empty slots before the first item after a filler (0–7). Also used by first-row indentation.", position = 0)
    default int indent() { return 0; }

    @ConfigItem(keyName = "indentTabs", name = "Indent tab first rows", description = "Indent the first row of normal tabs, including their sections in All Items.", position = 1)
    default boolean indentTabs() { return false; }

    @ConfigItem(keyName = "indentAllItems", name = "Indent All Items first row", description = "Separately indent the very first row of the All Items view.", position = 2)
    default boolean indentAllItems() { return false; }

    @ConfigItem(keyName = "blankRow", name = "Blank row between sections", description = "Leave a completely empty row after each filler before placing the following items.", position = 3)
    default boolean blankRow() { return false; }
    @ConfigItem(keyName = "ignoreConsecutiveFillers", name = "Ignore consecutive fillers", description = "Only the first filler in a consecutive run creates a row break. Remaining fillers stay visible and occupy ordinary slots.", position = 4)
    default boolean ignoreConsecutiveFillers() { return true; }
}

package com.bankrowbreaks;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import com.google.inject.Provides;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsPlugin;

@Slf4j
@PluginDescriptor(
    name = "Bank Filler Line Break",
    description = "Treat bank fillers as visual row breaks in normal bank tabs",
    tags = {"bank", "filler", "layout", "rows"}
)
public class BankRowBreaksPlugin extends Plugin
{
    @Inject BankRowBreaksConfig config;
    @Inject Client client;
    @Inject ClientThread clientThread;
    @Inject BankSearch bankSearch;
    @Inject PluginManager pluginManager;
    private boolean enabled;
    private boolean filteredBuild;
    private String lastStatus;

    @Provides
    BankRowBreaksConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(BankRowBreaksConfig.class);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (BankRowBreaksConfig.GROUP.equals(event.getGroup()))
        {
            clientThread.invokeLater(() -> {
                if (enabled) { bankSearch.layoutBank(); }
            });
        }
    }

    @Override
    protected void startUp()
    {
        enabled = true;
        lastStatus = null;
        log.info("Bank Filler Line Break 0.2.2 enabled");
        clientThread.invokeLater(bankSearch::layoutBank);
    }

    @Override
    protected void shutDown()
    {
        enabled = false;
        filteredBuild = false;
        clientThread.invokeLater(bankSearch::layoutBank);
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if ("bankSearchFilter".equals(event.getEventName()))
        {
            int size = client.getObjectStackSize();
            if (size > 0)
            {
                Object filter = client.getObjectStack()[size - 1];
                filteredBuild |= filter instanceof String && !((String) filter).isEmpty();
            }
        }
    }

    @Subscribe(priority = -1)
    public void onScriptPreFired(ScriptPreFired event)
    {
        if (event.getScriptId() == ScriptID.BANKMAIN_BUILD)
        {
            filteredBuild = false;
        }
        if (enabled && event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING)
        {
            applyLayout();
        }
    }

    private void applyLayout()
    {
        int currentTab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
        // Normal bank tabs are 0..9; e.g. potion storage uses a synthetic tab 15.
        if (filteredBuild || currentTab < 0 || currentTab > 9)
        {
            status("Skipped: search=" + filteredBuild + ", tab=" + currentTab);
            return;
        }
        for (Plugin plugin : pluginManager.getPlugins())
        {
            if (plugin instanceof BankTagsPlugin
                && ((BankTagsPlugin) plugin).getActiveBankTag() != null)
            {
                status("Skipped: active RuneLite bank tag");
                return;
            }
        }
        Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
        ItemContainer bank = client.getItemContainer(InventoryID.BANK);
        if (container == null || bank == null || container.getChildren() == null)
        {
            status("Skipped: bank widgets or item container unavailable");
            return;
        }
        List<Widget> items = new ArrayList<>();
        List<Widget> decorations = new ArrayList<>();
        boolean hasFiller = false;
        for (Widget child : container.getChildren())
        {
            if (child == null || child.isSelfHidden())
            {
                continue;
            }
            int index = child.getIndex();
            if (child.getItemId() >= 0 && child.getItemId() != ItemID.BLANKOBJECT
                && child.getOriginalHeight() == RowLayout.ITEM_HEIGHT)
            {
                // Skip synthetic/reordered widgets belonging to other layouts.
                if (index < 0 || index >= bank.size() || bank.getItem(index) == null
                    || bank.getItem(index).getId() != child.getItemId())
                {
                    status("Skipped: widget/bank mismatch at slot " + index);
                    return;
                }
                items.add(child);
                hasFiller |= child.getItemId() == ItemID.BANK_FILLER;
            }
            else
            {
                decorations.add(child);
            }
        }
        boolean indentFirst = currentTab == 0 ? config.indentAllItems() : config.indentTabs();
        if (!hasFiller && !(config.indent() > 0 && (indentFirst || config.indentTabs())))
        {
            status("Skipped: no visible fillers among " + items.size() + " bank items");
            return;
        }
        items.sort(Comparator.comparingInt(Widget::getOriginalY)
            .thenComparingInt(Widget::getOriginalX));
        List<RowLayout.Cell> cells = new ArrayList<>();
        for (Widget item : items)
        {
            cells.add(new RowLayout.Cell(item.getOriginalX(), item.getOriginalY(),
                item.getItemId() == ItemID.BANK_FILLER));
        }
        // bankmain_finishbuilding has 22 int arguments. int13 is scroll height,
        // nine from the stack end, as in RuneLite Bank Tags' TabInterface.
        int stackSize = client.getIntStackSize();
        if (stackSize < 22)
        {
            status("Skipped: unexpected script stack size " + stackSize);
            return;
        }
        RowLayout.Result layout = RowLayout.arrange(cells, config.indent(), indentFirst,
            config.indentTabs(), config.blankRow(), config.ignoreConsecutiveFillers());
        for (int i = 0; i < items.size(); i++)
        {
            Widget item = items.get(i);
            RowLayout.Cell cell = layout.cells.get(i);
            item.setOriginalX(cell.x);
            item.setOriginalY(cell.y);
            item.revalidate();
        }
        for (Widget decoration : decorations)
        {
            int offset = layout.decorationOffset(decoration.getOriginalY());
            if (offset != 0)
            {
                decoration.setOriginalY(decoration.getOriginalY() + offset);
                decoration.revalidate();
            }
        }
        client.getIntStack()[stackSize - 9] += layout.extraHeight;
        status("Applied to " + items.size() + " items; extra height=" + layout.extraHeight
            + ", column spacing=" + RowLayout.columnSpacing(cells));
    }

    // Log only when the outcome changes; do not flood logs on bank rebuilds.
    private void status(String message)
    {
        if (!message.equals(lastStatus))
        {
            log.debug("Bank Filler Line Break: {}", message);
            lastStatus = message;
        }
    }
}

package com.bankrowbreaks;

import java.util.ArrayList;
import java.util.List;

/** Input is native bank geometry, never the previous output. */
final class RowLayout
{
    static final int COLUMNS = 8;
    static final int X_STEP = 48;
    static final int Y_STEP = 36;
    static final int ITEM_HEIGHT = 32;

    static final class Cell
    {
        final int x;
        final int y;
        final boolean filler;
        Cell(int x, int y, boolean filler)
        {
            this.x = x;
            this.y = y;
            this.filler = filler;
        }
    }

    static final class Result
    {
        final List<Cell> cells = new ArrayList<>();
        final List<int[]> boundaries = new ArrayList<>();
        int extraHeight;
        int decorationOffset(int originalY)
        {
            int offset = 0;
            for (int[] boundary : boundaries)
            {
                if (originalY >= boundary[0])
                {
                    offset = boundary[1];
                }
            }
            return offset;
        }
    }

    static int columnSpacing(List<Cell> input)
    {
        int spacing = Integer.MAX_VALUE;
        for (int i = 1; i < input.size(); i++)
        {
            Cell previous = input.get(i - 1);
            Cell current = input.get(i);
            int difference = current.x - previous.x;
            if (current.y == previous.y && difference > 0)
            {
                spacing = Math.min(spacing, difference);
            }
        }
        return spacing == Integer.MAX_VALUE ? X_STEP : spacing;
    }

    static Result arrange(List<Cell> input)
    {
        return arrange(input, 0, false, false, false);
    }

    static Result arrange(List<Cell> input, int requestedIndent, boolean indentFirst,
        boolean indentLaterTabs, boolean blankRow)
    {
        return arrange(input, requestedIndent, indentFirst, indentLaterTabs, blankRow, false);
    }

    static Result arrange(List<Cell> input, int requestedIndent, boolean indentFirst,
        boolean indentLaterTabs, boolean blankRow, boolean ignoreConsecutiveFillers)
    {
        int indent = Math.max(0, Math.min(7, requestedIndent));
        int xStep = columnSpacing(input);
        Result result = new Result();
        int start = 0;
        while (start < input.size())
        {
            Cell first = input.get(start);
            int end = start + 1;
            // Tab headings and partial final rows separate native grid segments.
            while (end < input.size())
            {
                int index = end - start;
                Cell next = input.get(end);
                if (next.x != first.x + index % COLUMNS * xStep
                    || next.y != first.y + index / COLUMNS * Y_STEP)
                {
                    break;
                }
                end++;
            }
            int slot = (start == 0 ? indentFirst : indentLaterTabs) ? indent : 0;
            int lastSlot = 0;
            for (int i = start; i < end; i++)
            {
                Cell cell = input.get(i);
                lastSlot = slot;
                result.cells.add(new Cell(first.x + slot % COLUMNS * xStep,
                    first.y + result.extraHeight + slot / COLUMNS * Y_STEP, cell.filler));
                slot++;
                if (cell.filler && (!ignoreConsecutiveFillers || i == start || !input.get(i - 1).filler))
                {
                    // Column eight already ends the row.
                    slot = (slot + COLUMNS - 1) / COLUMNS * COLUMNS
                        + (blankRow ? COLUMNS : 0) + indent;
                }
            }
            int oldRows = (end - start + COLUMNS - 1) / COLUMNS;
            int newRows = lastSlot / COLUMNS + 1;
            result.extraHeight += (newRows - oldRows) * Y_STEP;
            result.boundaries.add(new int[] {
                input.get(end - 1).y + ITEM_HEIGHT, result.extraHeight
            });
            start = end;
        }
        return result;
    }
}

package com.bankrowbreaks;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BankRowBreaksLauncher
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(BankRowBreaksPlugin.class);
        RuneLite.main(args);
    }
}

package com.bankrowbreaks;

import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BankRowBreaksPluginTest
{
    private BankRowBreaksPlugin plugin;
    private Client client;
    private Widget[] widgets;
    private int[] stack;

    @Before public void setup()
    {
        plugin = new BankRowBreaksPlugin();
        plugin.config = mock(BankRowBreaksConfig.class);
        client = mock(Client.class);
        plugin.client = client;
        plugin.clientThread = mock(ClientThread.class);
        plugin.bankSearch = mock(BankSearch.class);
        plugin.pluginManager = mock(PluginManager.class);
        when(plugin.pluginManager.getPlugins()).thenReturn(Collections.emptyList());
        Widget container = mock(Widget.class);
        ItemContainer bank = mock(ItemContainer.class);
        when(client.getWidget(InterfaceID.Bankmain.ITEMS)).thenReturn(container);
        when(client.getItemContainer(InventoryID.BANK)).thenReturn(bank);
        when(bank.size()).thenReturn(8);
        widgets = new Widget[8];
        for (int i = 0; i < widgets.length; i++)
        {
            int id = i == 3 ? ItemID.BANK_FILLER : 100 + i;
            widgets[i] = mock(Widget.class);
            when(widgets[i].getIndex()).thenReturn(i);
            when(widgets[i].getItemId()).thenReturn(id);
            when(widgets[i].getOriginalHeight()).thenReturn(32);
            when(widgets[i].getOriginalX()).thenReturn(51 + i * 48);
            when(bank.getItem(i)).thenReturn(new Item(id, 1));
        }
        when(container.getChildren()).thenReturn(widgets);
        stack = new int[32];
        stack[13] = 36;
        when(client.getIntStack()).thenReturn(stack);
        when(client.getIntStackSize()).thenReturn(22);
        plugin.startUp();
        fire(ScriptID.BANKMAIN_BUILD);
    }

    private void fire(int id)
    {
        ScriptPreFired event = mock(ScriptPreFired.class);
        when(event.getScriptId()).thenReturn(id);
        plugin.onScriptPreFired(event);
    }

    private void filter(String text)
    {
        when(client.getObjectStack()).thenReturn(new Object[] {text});
        when(client.getObjectStackSize()).thenReturn(1);
        ScriptCallbackEvent event = mock(ScriptCallbackEvent.class);
        when(event.getEventName()).thenReturn("bankSearchFilter");
        plugin.onScriptCallbackEvent(event);
    }

    @Test public void normalBuildMovesWidgetsAndExtendsScrollHeight()
    {
        filter("");
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalX(51);
        verify(widgets[4]).setOriginalY(36);
        verify(widgets[7]).setOriginalY(36);
        verify(widgets[4], never()).setItemId(anyInt());
        assertEquals(72, stack[13]);
    }

    @Test public void searchIsUntouchedAndNextBuildResetsFilter()
    {
        filter("rune");
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4], never()).setOriginalY(anyInt());
        assertEquals(36, stack[13]);
        fire(ScriptID.BANKMAIN_BUILD);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalY(36);
    }

    @Test public void rememberedFillerSelectionDoesNotDisableRowBreaks()
    {
        // This is a persistent selection, not an editing-mode boolean.
        when(client.getVarbitValue(VarbitID.BANK_FILLERMODE)).thenReturn(1);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalY(36);
        assertEquals(72, stack[13]);
    }

    @Test public void potionStorageIsUntouched()
    {
        when(client.getVarbitValue(VarbitID.BANK_CURRENTTAB)).thenReturn(15);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4], never()).setOriginalY(anyInt());
    }

    @Test public void syntheticWidgetsAreUntouched()
    {
        when(widgets[0].getItemId()).thenReturn(999);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4], never()).setOriginalY(anyInt());
    }

    @Test public void shutdownStopsApplyingLayout()
    {
        plugin.shutDown();
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4], never()).setOriginalY(anyInt());
    }
    @Test public void indentAndBlankRowCombineAfterFiller()
    {
        when(plugin.config.indent()).thenReturn(2);
        when(plugin.config.blankRow()).thenReturn(true);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalX(147);
        verify(widgets[4]).setOriginalY(72);
    }

    @Test public void firstRowOptionsAreIndependentWithoutFillers()
    {
        when(widgets[3].getItemId()).thenReturn(103);
        when(client.getItemContainer(InventoryID.BANK).getItem(3)).thenReturn(new Item(103, 1));
        when(plugin.config.indent()).thenReturn(2);
        when(plugin.config.indentTabs()).thenReturn(true);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[0]).setOriginalX(51);
        clearInvocations(widgets[0]);
        when(client.getVarbitValue(VarbitID.BANK_CURRENTTAB)).thenReturn(1);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[0]).setOriginalX(147);
        clearInvocations(widgets[0]);
        when(client.getVarbitValue(VarbitID.BANK_CURRENTTAB)).thenReturn(0);
        when(plugin.config.indentTabs()).thenReturn(false);
        when(plugin.config.indentAllItems()).thenReturn(true);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[0]).setOriginalX(147);
    }
    @Test public void optionChangeRebuildsBankOnClientThread()
    {
        clearInvocations(plugin.clientThread);
        net.runelite.client.events.ConfigChanged event = mock(net.runelite.client.events.ConfigChanged.class);
        when(event.getGroup()).thenReturn(BankRowBreaksConfig.GROUP);
        plugin.onConfigChanged(event);
        org.mockito.ArgumentCaptor<Runnable> task = org.mockito.ArgumentCaptor.forClass(Runnable.class);
        verify(plugin.clientThread).invokeLater(task.capture());
        verify(plugin.bankSearch, never()).layoutBank();
        task.getValue().run();
        verify(plugin.bankSearch).layoutBank();
    }

    @Test public void defaultsPreserveExistingBehavior()
    {
        BankRowBreaksConfig defaults = new BankRowBreaksConfig() {};
        assertEquals(0, defaults.indent());
        assertFalse(defaults.indentTabs());
        assertFalse(defaults.indentAllItems());
        assertFalse(defaults.blankRow());
        assertTrue(defaults.ignoreConsecutiveFillers());
    }
    @Test public void consecutiveFillerSettingIsAppliedToBankWidgets()
    {
        when(widgets[2].getItemId()).thenReturn(ItemID.BANK_FILLER);
        when(client.getItemContainer(InventoryID.BANK).getItem(2)).thenReturn(new Item(ItemID.BANK_FILLER, 1));
        when(plugin.config.ignoreConsecutiveFillers()).thenReturn(true);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalX(99);
        verify(widgets[4]).setOriginalY(36);
        clearInvocations(widgets[4]);
        when(plugin.config.ignoreConsecutiveFillers()).thenReturn(false);
        fire(ScriptID.BANKMAIN_FINISHBUILDING);
        verify(widgets[4]).setOriginalX(51);
        verify(widgets[4]).setOriginalY(72);
    }
}

package com.bankrowbreaks;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;
import static org.junit.Assert.*;

public class RowLayoutTest
{
    private List<RowLayout.Cell> grid(int count, int... fillers)
    {
        List<RowLayout.Cell> cells = new ArrayList<>();
        for (int i = 0; i < count; i++)
        {
            boolean filler = false;
            for (int f : fillers) { filler |= f == i; }
            cells.add(new RowLayout.Cell(51 + i % 8 * 48, i / 8 * 36, filler));
        }
        return cells;
    }

    @Test public void emptyBank()
    {
        RowLayout.Result r = RowLayout.arrange(grid(0));
        assertTrue(r.cells.isEmpty());
        assertEquals(0, r.extraHeight);
    }

    @Test public void ordinaryBankUnchanged()
    {
        List<RowLayout.Cell> input = grid(100);
        RowLayout.Result r = RowLayout.arrange(input);
        for (int i = 0; i < input.size(); i++)
        {
            assertEquals(input.get(i).x, r.cells.get(i).x);
            assertEquals(input.get(i).y, r.cells.get(i).y);
        }
        assertEquals(0, r.extraHeight);
    }

    @Test public void middleFillerWrapsNextItem()
    {
        RowLayout.Result r = RowLayout.arrange(grid(8, 3));
        assertEquals(195, r.cells.get(3).x);
        assertEquals(0, r.cells.get(3).y);
        assertEquals(51, r.cells.get(4).x);
        assertEquals(36, r.cells.get(4).y);
        assertEquals(36, r.extraHeight);
    }

    @Test public void lastColumnDoesNotSkipExtraRow()
    {
        RowLayout.Result r = RowLayout.arrange(grid(9, 7));
        assertEquals(51, r.cells.get(8).x);
        assertEquals(36, r.cells.get(8).y);
        assertEquals(0, r.extraHeight);
    }

    @Test public void firstColumnAndConsecutiveFillers()
    {
        RowLayout.Result r = RowLayout.arrange(grid(4, 0, 1));
        assertEquals(0, r.cells.get(0).y);
        assertEquals(36, r.cells.get(1).y);
        assertEquals(72, r.cells.get(2).y);
        assertEquals(51, r.cells.get(2).x);
        assertEquals(99, r.cells.get(3).x);
    }

    @Test public void trailingFillerDoesNotAddEmptyRow()
    {
        assertEquals(0, RowLayout.arrange(grid(4, 3)).extraHeight);
    }

    @Test public void laterTabAndHeaderShiftTogether()
    {
        List<RowLayout.Cell> input = grid(8, 2);
        input.add(new RowLayout.Cell(51, 76, false));
        input.add(new RowLayout.Cell(99, 76, false));
        RowLayout.Result r = RowLayout.arrange(input);
        assertEquals(112, r.cells.get(8).y);
        assertEquals(36, r.decorationOffset(50));
        assertEquals(0, r.decorationOffset(0));
        assertEquals(36, r.extraHeight);
    }

    @Test public void partialTabPreservesNextTabBoundary()
    {
        List<RowLayout.Cell> input = grid(4, 1);
        input.add(new RowLayout.Cell(51, 76, false));
        RowLayout.Result r = RowLayout.arrange(input);
        assertEquals(36, r.cells.get(2).y);
        assertEquals(112, r.cells.get(4).y);
    }

    @Test public void repeatedBuildFromNativeGeometryDoesNotAccumulate()
    {
        List<RowLayout.Cell> input = grid(30, 2, 15);
        RowLayout.Result a = RowLayout.arrange(input);
        RowLayout.Result b = RowLayout.arrange(input);
        assertEquals(a.extraHeight, b.extraHeight);
        for (int i = 0; i < input.size(); i++)
        {
            assertEquals(a.cells.get(i).x, b.cells.get(i).x);
            assertEquals(a.cells.get(i).y, b.cells.get(i).y);
        }
    }

    @Test public void randomizedBanksPreserveOrderAndBreaks()
    {
        Random random = new Random(12345);
        for (int trial = 0; trial < 500; trial++)
        {
            List<RowLayout.Cell> input = grid(1 + random.nextInt(1000));
            for (int i = 0; i < input.size(); i++)
            {
                RowLayout.Cell c = input.get(i);
                input.set(i, new RowLayout.Cell(c.x, c.y, random.nextInt(5) == 0));
            }
            RowLayout.Result r = RowLayout.arrange(input);
            int previous = -1;
            for (int i = 0; i < r.cells.size(); i++)
            {
                RowLayout.Cell c = r.cells.get(i);
                int slot = c.y / 36 * 8 + (c.x - 51) / 48;
                assertTrue(slot > previous);
                assertEquals(input.get(i).filler, c.filler);
                if (i > 0 && input.get(i - 1).filler)
                {
                    assertEquals(51, c.x);
                    assertEquals((previous / 8 + 1) * 36, c.y);
                }
                previous = slot;
            }
            int oldBottom = input.get(input.size() - 1).y + 32;
            int newBottom = r.cells.get(r.cells.size() - 1).y + 32;
            assertEquals(newBottom - oldBottom, r.extraHeight);
        }
    }
    @Test public void widerBankStillWrapsAfterFiller()
    {
        for (int spacing : new int[] {42, 49, 54, 60, 72})
        {
            List<RowLayout.Cell> input = new ArrayList<>();
            for (int i = 0; i < 16; i++)
            {
                input.add(new RowLayout.Cell(51 + i % 8 * spacing, i / 8 * 36, i == 3));
            }
            RowLayout.Result r = RowLayout.arrange(input);
            assertEquals(spacing, RowLayout.columnSpacing(input));
            assertEquals(51, r.cells.get(4).x);
            assertEquals(36, r.cells.get(4).y);
            assertEquals(51 + spacing, r.cells.get(5).x);
            assertEquals(36, r.extraHeight);
        }
    }
    @Test public void indentClampsAndOnlyAffectsSectionStarts()
    {
        for (int requested : new int[] {-20, 0, 1, 7, 99})
        {
            int indent = Math.max(0, Math.min(7, requested));
            RowLayout.Result r = RowLayout.arrange(grid(20, 3), requested, false, false, false);
            assertEquals(51, r.cells.get(0).x);
            assertEquals(51 + indent * 48, r.cells.get(4).x);
            assertEquals(36, r.cells.get(4).y);
            assertEquals(51, r.cells.get(12 - indent).x);
            assertEquals(72, r.cells.get(12 - indent).y);
        }
    }

